/**
 * Sub-issue tree rules: loop and depth checks, descendant walks and the
 * closed/open split behind roll-ups.
 *
 * Pure functions over a flat list of issues from one project. The service
 * layer loads that list and decides what to do with the answer; nothing here
 * touches the database or the event bus.
 */
import { MAX_SUB_ISSUE_DEPTH } from "@/config/constants";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import type { IssueId } from "@/types/common";
