/**
 * Sub-issues: placement, depth and loop refusals, listing, roll-up, cascade
 * archiving and the completion notice.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { IssueHierarchyError } from "@/lib/issue-hierarchy";
import { NotFoundError } from "@/server/services/_support";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as issueService from "@/server/services/issue-service";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Issue } from "@/types/issue";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("subissues");
  other = await createTenant("subissuesother");
});

afterAll(() => {
  cleanup();
});

async function makeIssue(
  title: string,
  overrides: { parentId?: Issue["id"] | null; assigneeId?: Issue["assigneeId"]; projectId?: Issue["projectId"] } = {},
): Promise<Issue> {
  return issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, overrides.projectId ?? tenant.project.id, {
      title,
      parentId: overrides.parentId ?? null,
      assigneeId: overrides.assigneeId ?? null,
    }),
  );
}

function capture<K extends TaskflowEventType>(type: K): {
  seen: TaskflowEventMap[K][];
  off: Unsubscribe;
} {
  const seen: TaskflowEventMap[K][] = [];
  const off = subscribe(type, (payload) => {
    seen.push(payload);
  });
  return { seen, off };
}

describe("setIssueParent", () => {
  it("places an issue under a parent and reports the change as issue.updated", async () => {
    const parent = await makeIssue("Parent for placement");
    const child = await makeIssue("Child for placement");

    const updated = capture("issue.updated");
    try {
      const stored = await issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: parent.id,
      });

      expect(stored.parentId).toBe(parent.id);
      expect(updated.seen).toHaveLength(1);
      expect(updated.seen[0]?.changedFields).toEqual(["parentId"]);
    } finally {
      updated.off();
    }
  });

  it("makes an issue a root again with null", async () => {
    const parent = await makeIssue("Parent for detach");
    const child = await makeIssue("Child for detach", { parentId: parent.id });

    const stored = await issueService.setIssueParent(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child.id,
      parentId: null,
    });

    expect(stored.parentId).toBeNull();
  });

  it("refuses a parent from another project as not found", async () => {
    const elsewhere = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Elsewhere",
      slug: "elsewhere-sub",
      key: "ELS",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const foreignParent = await makeIssue("Foreign parent", { projectId: elsewhere.id });
    const child = await makeIssue("Local child");

    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: foreignParent.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses a parent from another workspace as not found", async () => {
    const foreign = await makeIssue("Other workspace parent", {});
    const foreignIssue = await issueService.createIssue(
      other.actors.member,
      issueInput(other.org.id, other.project.id, { title: "Other workspace issue" }),
    );
    const child = await makeIssue("Local child for workspace");

    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: foreignIssue.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect(foreign.id).not.toBe(foreignIssue.id);
  });

  it("refuses an archived parent as already archived", async () => {
    const parent = await makeIssue("Archived parent");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, parent.id);
    const child = await makeIssue("Child of archived parent");

    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: parent.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("refuses a loop, including placing an issue under itself", async () => {
    const top = await makeIssue("Loop top");
    const middle = await makeIssue("Loop middle", { parentId: top.id });

    const error = await issueService
      .setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: top.id,
        parentId: middle.id,
      })
      .catch((caught: unknown) => caught);
    expect(error).toBeInstanceOf(IssueHierarchyError);
    expect((error as IssueHierarchyError).reason).toBe("cycle");

    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: top.id,
        parentId: top.id,
      }),
    ).rejects.toBeInstanceOf(IssueHierarchyError);
  });

  it("refuses a move that would push the deepest descendant past the maximum depth, changing nothing", async () => {
    const a = await makeIssue("Depth a");
    const b = await makeIssue("Depth b", { parentId: a.id });
    const c = await makeIssue("Depth c", { parentId: b.id });
    const d = await makeIssue("Depth d", { parentId: c.id });
    const lone = await makeIssue("Depth lone");

    // a→b→c→d already sits at level 3; putting `lone` under `d` would be level 4.
    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: lone.id,
        parentId: d.id,
      }),
    ).rejects.toMatchObject({ reason: "too_deep" });

    // Moving `a` (with three levels below it) under any issue is too deep.
    const holder = await makeIssue("Depth holder");
    const holderChild = await makeIssue("Depth holder child", { parentId: holder.id });
    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: a.id,
        parentId: holderChild.id,
      }),
    ).rejects.toMatchObject({ reason: "too_deep" });

    const unchanged = await issueRepo.findIssueById(tenant.org.id, a.id);
    expect(unchanged?.parentId).toBeNull();
  });

  it("refuses an archived issue being moved", async () => {
    const parent = await makeIssue("Move-archived parent");
    const child = await makeIssue("Move-archived child");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, child.id);

    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: parent.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("requires issue:update on the issue", async () => {
    const parent = await makeIssue("Viewer parent");
    const child = await makeIssue("Viewer child");

    await expect(
      issueService.setIssueParent(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: parent.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("refuses an actor from another workspace", async () => {
    const parent = await makeIssue("Scope parent");
    const child = await makeIssue("Scope child");

    await expect(
      issueService.setIssueParent(other.actors.owner, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: parent.id,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

describe("createIssue with a parent", () => {
  it("creates under a live parent of the same project", async () => {
    const parent = await makeIssue("Created-under parent");
    const child = await makeIssue("Created-under child", { parentId: parent.id });

    expect(child.parentId).toBe(parent.id);
  });

  it("creates nothing and announces nothing when the parent is refused", async () => {
    const created = capture("issue.created");
    try {
      await expect(
        issueService.createIssue(
          tenant.actors.member,
          issueInput(tenant.org.id, tenant.project.id, {
            title: "Refused under archived",
            parentId: (await makeArchivedIssue()).id,
          }),
        ),
      ).rejects.toBeInstanceOf(AlreadyArchivedError);
      expect(created.seen.filter((p) => p.title === "Refused under archived")).toHaveLength(0);
    } finally {
      created.off();
    }
  });
});

async function makeArchivedIssue(): Promise<Issue> {
  const issue = await makeIssue("Archived before refused create");
  return issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
}

describe("listSubIssues", () => {
  it("lists direct live sub-issues, oldest first", async () => {
    const parent = await makeIssue("List parent");
    const first = await makeIssue("List first", { parentId: parent.id });
    const second = await makeIssue("List second", { parentId: parent.id });
    const grandchild = await makeIssue("List grandchild", { parentId: first.id });
    const gone = await makeIssue("List archived", { parentId: parent.id });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, gone.id);

    const children = await issueService.listSubIssues(tenant.actors.viewer, tenant.org.id, parent.id);

    expect(children.map((issue) => issue.id)).toEqual([first.id, second.id]);
    expect(children.map((issue) => issue.id)).not.toContain(grandchild.id);
  });

  it("refuses an issue of another workspace as not found", async () => {
    const foreign = await issueService.createIssue(
      other.actors.member,
      issueInput(other.org.id, other.project.id, { title: "Foreign list issue" }),
    );

    await expect(
      issueService.listSubIssues(tenant.actors.member, tenant.org.id, foreign.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });
});

describe("getIssueRollup", () => {
  it("counts every live issue below at any depth, closed meaning done or canceled", async () => {
    const root = await makeIssue("Rollup root");
    const a = await makeIssue("Rollup a", { parentId: root.id });
    const b = await makeIssue("Rollup b", { parentId: a.id });
    const c = await makeIssue("Rollup c", { parentId: root.id });
    const dead = await makeIssue("Rollup dead", { parentId: root.id });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: c.id,
      status: "done",
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: dead.id,
      status: "canceled",
    });
    const archived = await makeIssue("Rollup archived", { parentId: root.id });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archived.id);

    const rollup = await issueService.getIssueRollup(tenant.actors.viewer, tenant.org.id, root.id);

    expect(rollup).toEqual({ total: 4, open: 2, closed: 2 });
    expect(b.id).toBeDefined();
  });
});

describe("archiving with sub-issues", () => {
  it("archives every live issue below, announcing each once, and leaves the parent alone", async () => {
    const top = await makeIssue("Cascade top");
    const mid = await makeIssue("Cascade mid", { parentId: top.id });
    const leaf = await makeIssue("Cascade leaf", { parentId: mid.id });
    const archivedEarlier = await makeIssue("Cascade earlier", { parentId: mid.id });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archivedEarlier.id);

    const archived = capture("issue.archived");
    try {
      await issueService.archiveIssue(tenant.actors.member, tenant.org.id, mid.id);

      expect(archived.seen.map((payload) => payload.issueId).sort()).toEqual(
        [mid.id, leaf.id].sort(),
      );

      const stored = await issueRepo.findIssueById(tenant.org.id, leaf.id);
      expect(stored?.archivedAt).not.toBeNull();
      const parent = await issueRepo.findIssueById(tenant.org.id, top.id);
      expect(parent?.archivedAt).toBeNull();
    } finally {
      archived.off();
    }
  });
});

describe("sub-issue completion notice", () => {
  it("tells the parent's assignee once when the last open sub-issue closes", async () => {
    const assignee = tenant.userIds.admin;
    const parent = await makeIssue("Notice parent", { assigneeId: assignee });
    const child = await makeIssue("Notice child", { parentId: parent.id });
    const sibling = await makeIssue("Notice sibling", { parentId: parent.id });

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child.id,
      status: "done",
    });
    const beforeLast = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: assignee,
      unreadOnly: false,
      kind: ["sub_issues_completed"],
      limit: 50,
      cursor: null,
    });
    expect(beforeLast.items.filter((n) => n.href === `/issues/${parent.id}`)).toHaveLength(0);

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: sibling.id,
      status: "canceled",
    });
    const afterLast = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: assignee,
      unreadOnly: false,
      kind: ["sub_issues_completed"],
      limit: 50,
      cursor: null,
    });
    expect(afterLast.items.filter((n) => n.href === `/issues/${parent.id}`)).toHaveLength(1);
  });

  it("stays silent for a reopen or a closed-to-closed change", async () => {
    const parent = await makeIssue("Silent parent", { assigneeId: tenant.userIds.admin });
    const child = await makeIssue("Silent child", { parentId: parent.id });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child.id,
      status: "done",
    });

    const seen = capture("issue.sub_issues_completed");
    try {
      await issueService.changeIssueStatus(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        status: "canceled",
      });
      expect(seen.seen).toHaveLength(0);
    } finally {
      seen.off();
    }
  });
});

